cd /tmp && cat > fuzz3.py <<'PY'
import struct, subprocess, os, random, sys

BIN = "/workspace/artifacts/target/jasper"
ref = open('/tmp/ref.jpc','rb').read()

def run(data, timeout=2):
    open('/tmp/fz.jpc','wb').write(data)
    try:
        p = subprocess.run([BIN,'-f','/tmp/fz.jpc','-t','jpc','-F','/dev/null','-T','pnm'],
                           capture_output=True, timeout=timeout)
        return p.returncode, p.stderr.decode('latin1')
    except subprocess.TimeoutExpired:
        return 'TIMEOUT',''

hits=0
# single-byte mutations: try every byte, every value 0..255
for i in range(len(ref)):
    for v in range(256):
        if ref[i]==v: continue
        d = bytearray(ref); d[i]=v
        rc,err = run(bytes(d))
        if rc in ('TIMEOUT',) or (isinstance(rc,int) and rc<0):
            print("HIT idx",i,"val",v,"rc",rc,"err",err[:100])
            open('/tmp/hit_sb_%d.jpc'%hits,'wb').write(bytes(d)); hits+=1
            if hits>=5: sys.exit(0)
print("done single-byte, hits",hits)
PY
